DROP PROCEDURE IF EXISTS `nascar`.`agg_hist_weeks_track_drivers_stats`;

DELIMITER //

CREATE PROCEDURE `nascar`.`agg_hist_weeks_track_drivers_stats`(
    IN `r_series_id` BIGINT UNSIGNED,
    IN `r_season_id` BIGINT UNSIGNED,
    IN `r_week_id` BIGINT UNSIGNED
)
COMMENT 'Aggregate statistics for a specific race week in the NASCAR series, including practices, qualifying, race results, as well as penalties and pitstops.'
BEGIN
    SELECT
        r_series_id AS series_id,
        r_season_id AS season_id,
        r_week_id AS week_id,
        hws.track_id,
        hws.driver_id,
        ROUND(AVG(hws.race_start_position), 3) as race_avg_start_position,
        ROUND(STDDEV_SAMP(hws.race_start_position), 3) as race_stddev_start_position,
        ROUND(AVG(CASE WHEN hws.race_start_position > 0 THEN LN(hws.race_start_position) END), 3) as race_ln_start_position,
        ROUND(AVG(hws.race_finish_position), 3) as race_avg_finish_position,
        ROUND(STDDEV_SAMP(hws.race_finish_position), 3) as race_stddev_finish_position,
        ROUND(AVG(CASE WHEN hws.race_finish_position > 0 THEN LN(hws.race_finish_position) END), 3) as race_ln_finish_position,
        ROUND(AVG(hws.race_best_position), 3) as race_avg_best_position,
        ROUND(STDDEV_SAMP(hws.race_best_position), 3) as race_stddev_best_position,
        ROUND(AVG(CASE WHEN hws.race_best_position > 0 THEN LN(hws.race_best_position) END), 3) as race_ln_best_position,
        ROUND(AVG(hws.race_worst_position), 3) as race_avg_worst_position,
        ROUND(STDDEV_SAMP(hws.race_worst_position), 3) as race_stddev_worst_position,
        ROUND(AVG(CASE WHEN hws.race_worst_position > 0 THEN LN(hws.race_worst_position) END), 3) as race_ln_worst_position,
        ROUND(AVG(hws.race_average_position), 3) as race_avg_average_position,
        ROUND(STDDEV_SAMP(hws.race_average_position), 3) as race_stddev_average_position,
        ROUND(AVG(CASE WHEN hws.race_average_position > 0 THEN LN(hws.race_average_position) END), 3) as race_ln_average_position,
        ROUND(AVG(hws.race_green_flag_passes), 3) as race_avg_green_flag_passes,
        ROUND(STDDEV_SAMP(hws.race_green_flag_passes), 3) as race_stddev_green_flag_passes,
        ROUND(AVG(CASE WHEN hws.race_green_flag_passes > 0 THEN LN(hws.race_green_flag_passes) END), 3) as race_ln_green_flag_passes,
        ROUND(AVG(hws.race_green_flag_times_passed), 3) as race_avg_green_flag_times_passed,
        ROUND(STDDEV_SAMP(hws.race_green_flag_times_passed), 3) as race_stddev_green_flag_times_passed,
        ROUND(AVG(CASE WHEN hws.race_green_flag_times_passed > 0 THEN LN(hws.race_green_flag_times_passed) END), 3) as race_ln_green_flag_times_passed,
        ROUND(AVG(hws.race_green_flag_pass_diff), 3) as race_avg_green_flag_pass_diff,
        ROUND(STDDEV_SAMP(hws.race_green_flag_pass_diff), 3) as race_stddev_green_flag_pass_diff,
        ROUND(AVG(CBRT(hws.race_green_flag_pass_diff)), 3) as race_cbrt_green_flag_pass_diff,
        ROUND(AVG(hws.race_quality_passes), 3) as race_avg_quality_passes,
        ROUND(STDDEV_SAMP(hws.race_quality_passes), 3) as race_stddev_quality_passes,
        ROUND(AVG(CASE WHEN hws.race_quality_passes > 0 THEN LN(hws.race_quality_passes) END), 3) as race_ln_quality_passes,
        ROUND(AVG(hws.race_quality_passes_pct), 3) as race_avg_quality_passes_pct,
        ROUND(STDDEV_SAMP(hws.race_quality_passes_pct), 3) as race_stddev_quality_passes_pct,
        ROUND(AVG(CASE WHEN hws.race_quality_passes_pct > 0 THEN LN(hws.race_quality_passes_pct) END), 3) as race_ln_quality_passes_pct,
        ROUND(AVG(hws.race_total_fastest_laps), 3) as race_avg_total_fastest_laps,
        ROUND(STDDEV_SAMP(hws.race_total_fastest_laps), 3) as race_stddev_total_fastest_laps,
        ROUND(AVG(CASE WHEN hws.race_total_fastest_laps > 0 THEN LN(hws.race_total_fastest_laps) END), 3) as race_ln_total_fastest_laps,
        ROUND(AVG(hws.race_total_fastest_laps_pct), 3) as race_avg_total_fastest_laps_pct,
        ROUND(STDDEV_SAMP(hws.race_total_fastest_laps_pct), 3) as race_stddev_total_fastest_laps_pct,
        ROUND(AVG(CASE WHEN hws.race_total_fastest_laps_pct > 0 THEN LN(hws.race_total_fastest_laps_pct) END), 3) as race_ln_total_fastest_laps_pct,
        ROUND(AVG(hws.race_total_top_15_laps), 3) as race_avg_total_top_15_laps,
        ROUND(STDDEV_SAMP(hws.race_total_top_15_laps), 3) as race_stddev_total_top_15_laps,
        ROUND(AVG(CASE WHEN hws.race_total_top_15_laps > 0 THEN LN(hws.race_total_top_15_laps) END), 3) as race_ln_total_top_15_laps,
        ROUND(AVG(hws.race_total_top_15_laps_pct), 3) as race_avg_total_top_15_laps_pct,
        ROUND(STDDEV_SAMP(hws.race_total_top_15_laps_pct), 3) as race_stddev_total_top_15_laps_pct,
        ROUND(AVG(CASE WHEN hws.race_total_top_15_laps_pct > 0 THEN LN(hws.race_total_top_15_laps_pct) END), 3) as race_ln_total_top_15_laps_pct,
        ROUND(AVG(hws.race_total_laps_led), 3) as race_avg_total_laps_led,
        ROUND(STDDEV_SAMP(hws.race_total_laps_led), 3) as race_stddev_total_laps_led,
        ROUND(AVG(CASE WHEN hws.race_total_laps_led > 0 THEN LN(hws.race_total_laps_led) END), 3) as race_ln_total_laps_led,
        ROUND(AVG(hws.race_total_laps_led_pct), 3) as race_avg_total_laps_led_pct,
        ROUND(STDDEV_SAMP(hws.race_total_laps_led_pct), 3) as race_stddev_total_laps_led_pct,
        ROUND(AVG(CASE WHEN hws.race_total_laps_led_pct > 0 THEN LN(hws.race_total_laps_led_pct) END), 3) as race_ln_total_laps_led_pct,
        ROUND(AVG(hws.race_total_laps_completed), 3) as race_avg_total_laps_completed,
        ROUND(STDDEV_SAMP(hws.race_total_laps_completed), 3) as race_stddev_total_laps_completed,
        ROUND(AVG(CASE WHEN hws.race_total_laps_completed > 0 THEN LN(hws.race_total_laps_completed) END), 3) as race_ln_total_laps_completed,
        ROUND(AVG(hws.race_total_laps_completed_pct), 3) as race_avg_total_laps_completed_pct,
        ROUND(STDDEV_SAMP(hws.race_total_laps_completed_pct), 3) as race_stddev_total_laps_completed_pct,
        ROUND(AVG(CASE WHEN hws.race_total_laps_completed_pct > 0 THEN LN(hws.race_total_laps_completed_pct) END), 3) as race_ln_total_laps_completed_pct,
        ROUND(AVG(hws.race_driver_rating), 3) as race_avg_driver_rating,
        ROUND(STDDEV_SAMP(hws.race_driver_rating), 3) as race_stddev_driver_rating,
        ROUND(AVG(CASE WHEN hws.race_driver_rating > 0 THEN LN(hws.race_driver_rating) END), 3) as race_ln_driver_rating,
        ROUND(AVG(hws.race_avg_pitstop_crew_time), 3) as race_avg_pitstop_crew_time,
        ROUND(STDDEV_SAMP(hws.race_avg_pitstop_crew_time), 3) as race_stddev_pitstop_crew_time,
        ROUND(AVG(CASE WHEN hws.race_avg_pitstop_crew_time > 0 THEN LN(hws.race_avg_pitstop_crew_time) END), 3) as race_ln_pitstop_crew_time,
        ROUND(AVG(hws.race_avg_pitstop_driver_time), 3) as race_avg_pitstop_driver_time,
        ROUND(STDDEV_SAMP(hws.race_avg_pitstop_driver_time), 3) as race_stddev_pitstop_driver_time,
        ROUND(AVG(CASE WHEN hws.race_avg_pitstop_driver_time > 0 THEN LN(hws.race_avg_pitstop_driver_time) END), 3) as race_ln_pitstop_driver_time,
        ROUND(AVG(hws.race_total_pitstops), 3) as race_avg_total_pitstops,
        ROUND(STDDEV_SAMP(hws.race_total_pitstops), 3) as race_stddev_total_pitstops,
        ROUND(AVG(CASE WHEN hws.race_total_pitstops > 0 THEN LN(hws.race_total_pitstops) END), 3) as race_ln_total_pitstops,
        ROUND(AVG(hws.race_total_penalties), 3) as race_avg_total_penalties,
        ROUND(STDDEV_SAMP(hws.race_total_penalties), 3) as race_stddev_total_penalties,
        ROUND(AVG(CASE WHEN hws.race_total_penalties > 0 THEN LN(hws.race_total_penalties) END), 3) as race_ln_total_penalties,
        ROUND(AVG(hws.race_total_race_laps), 3) as race_avg_total_race_laps,
        ROUND(STDDEV_SAMP(hws.race_total_race_laps), 3) as race_stddev_total_race_laps,
        ROUND(AVG(CASE WHEN hws.race_total_race_laps > 0 THEN LN(hws.race_total_race_laps) END), 3) as race_ln_total_race_laps,
        ROUND(AVG(hws.race_total_race_miles), 3) as race_avg_total_race_miles,
        ROUND(STDDEV_SAMP(hws.race_total_race_miles), 3) as race_stddev_total_race_miles,
        ROUND(AVG(CASE WHEN hws.race_total_race_miles > 0 THEN LN(hws.race_total_race_miles) END), 3) as race_ln_total_race_miles,
        ROUND(AVG(hws.qualifying_finish_position), 3) as qualifying_avg_finish_position,
        ROUND(STDDEV_SAMP(hws.qualifying_finish_position), 3) as qualifying_stddev_finish_position,
        ROUND(AVG(CASE WHEN hws.qualifying_finish_position > 0 THEN LN(hws.qualifying_finish_position) END), 3) as qualifying_ln_finish_position,
        ROUND(AVG(hws.qualifying_best_speed), 3) as qualifying_avg_best_speed,
        ROUND(STDDEV_SAMP(hws.qualifying_best_speed), 3) as qualifying_stddev_best_speed,
        ROUND(AVG(CASE WHEN hws.qualifying_best_speed > 0 THEN LN(hws.qualifying_best_speed) END), 3) as qualifying_ln_best_speed,
        ROUND(AVG(hws.qualifying_best_time), 3) as qualifying_avg_best_time,
        ROUND(STDDEV_SAMP(TIME_TO_SEC(hws.qualifying_best_time)), 3) as qualifying_stddev_best_time,
        ROUND(AVG(CASE WHEN TIME_TO_SEC(hws.qualifying_best_time) > 0 THEN LN(TIME_TO_SEC(hws.qualifying_best_time)) END), 3) as qualifying_ln_best_time,
        ROUND(AVG(hws.practice_total_min_finish_position), 3) as practice_total_avg_min_finish_position,
        ROUND(STDDEV_SAMP(hws.practice_total_min_finish_position), 3) as practice_total_stddev_min_finish_position,
        ROUND(AVG(CASE WHEN hws.practice_total_min_finish_position > 0 THEN LN(hws.practice_total_min_finish_position) END), 3) as practice_total_ln_min_finish_position,
        ROUND(AVG(hws.practice_total_max_finish_position), 3) as practice_total_avg_max_finish_position,
        ROUND(STDDEV_SAMP(hws.practice_total_max_finish_position), 3) as practice_total_stddev_max_finish_position,
        ROUND(AVG(CASE WHEN hws.practice_total_max_finish_position > 0 THEN LN(hws.practice_total_max_finish_position) END), 3) as practice_total_ln_max_finish_position,
        ROUND(AVG(hws.practice_total_avg_finish_position), 3) as practice_total_avg_avg_finish_position,
        ROUND(STDDEV_SAMP(hws.practice_total_avg_finish_position), 3) as practice_total_stddev_avg_finish_position,
        ROUND(AVG(CASE WHEN hws.practice_total_avg_finish_position > 0 THEN LN(hws.practice_total_avg_finish_position) END), 3) as practice_total_ln_avg_finish_position,
        ROUND(AVG(hws.practice_total_min_best_speed), 3) as practice_total_avg_min_best_speed,
        ROUND(STDDEV_SAMP(hws.practice_total_min_best_speed), 3) as practice_total_stddev_min_best_speed,
        ROUND(AVG(CASE WHEN hws.practice_total_min_best_speed > 0 THEN LN(hws.practice_total_min_best_speed) END), 3) as practice_total_ln_min_best_speed,
        ROUND(AVG(hws.practice_total_max_best_speed), 3) as practice_total_avg_max_best_speed,
        ROUND(STDDEV_SAMP(hws.practice_total_max_best_speed), 3) as practice_total_stddev_max_best_speed,
        ROUND(AVG(CASE WHEN hws.practice_total_max_best_speed > 0 THEN LN(hws.practice_total_max_best_speed) END), 3) as practice_total_ln_max_best_speed,
        ROUND(AVG(hws.practice_total_avg_best_speed), 3) as practice_total_avg_best_speed,
        ROUND(STDDEV_SAMP(hws.practice_total_avg_best_speed), 3) as practice_total_stddev_best_speed,
        ROUND(AVG(CASE WHEN hws.practice_total_avg_best_speed > 0 THEN LN(hws.practice_total_avg_best_speed) END), 3) as practice_total_ln_best_speed,
        ROUND(AVG(hws.practice_total_min_best_time), 3) as practice_total_avg_min_best_time,
        ROUND(STDDEV_SAMP(TIME_TO_SEC(hws.practice_total_min_best_time)), 3) as practice_total_stddev_min_best_time,
        ROUND(AVG(CASE WHEN TIME_TO_SEC(hws.practice_total_min_best_time) > 0 THEN LN(TIME_TO_SEC(hws.practice_total_min_best_time)) END), 3) as practice_total_ln_min_best_time,
        ROUND(AVG(hws.practice_total_max_best_time), 3) as practice_total_avg_max_best_time,
        ROUND(STDDEV_SAMP(TIME_TO_SEC(hws.practice_total_max_best_time)), 3) as practice_total_stddev_max_best_time,
        ROUND(AVG(CASE WHEN TIME_TO_SEC(hws.practice_total_max_best_time) > 0 THEN LN(TIME_TO_SEC(hws.practice_total_max_best_time)) END), 3) as practice_total_ln_max_best_time,
        ROUND(AVG(hws.practice_total_avg_best_time), 3) as practice_total_avg_best_time,
        ROUND(STDDEV_SAMP(hws.practice_total_avg_best_time), 3) as practice_total_stddev_best_time,
        ROUND(AVG(CASE WHEN hws.practice_total_avg_best_time > 0 THEN LN(hws.practice_total_avg_best_time) END), 3) as practice_total_ln_best_time,
        ROUND(AVG(hws.practice_total_min_total_laps), 3) as practice_total_avg_min_total_laps,
        ROUND(STDDEV_SAMP(hws.practice_total_min_total_laps), 3) as practice_total_stddev_min_total_laps,
        ROUND(AVG(CASE WHEN hws.practice_total_min_total_laps > 0 THEN LN(hws.practice_total_min_total_laps) END), 3) as practice_total_ln_min_total_laps,
        ROUND(AVG(hws.practice_total_max_total_laps), 3) as practice_total_avg_max_total_laps,
        ROUND(STDDEV_SAMP(hws.practice_total_max_total_laps), 3) as practice_total_stddev_max_total_laps,
        ROUND(AVG(CASE WHEN hws.practice_total_max_total_laps > 0 THEN LN(hws.practice_total_max_total_laps) END), 3) as practice_total_ln_max_total_laps,
        ROUND(AVG(hws.practice_total_avg_total_laps), 3) as practice_total_avg_total_laps,
        ROUND(STDDEV_SAMP(hws.practice_total_avg_total_laps), 3) as practice_total_stddev_total_laps,
        ROUND(AVG(CASE WHEN hws.practice_total_avg_total_laps > 0 THEN LN(hws.practice_total_avg_total_laps) END), 3) as practice_total_ln_total_laps,
        ROUND(AVG(hws.practice_total_sum_total_laps), 3) as practice_total_avg_sum_total_laps,
        ROUND(STDDEV_SAMP(hws.practice_total_sum_total_laps), 3) as practice_total_stddev_sum_total_laps,
        ROUND(AVG(CASE WHEN hws.practice_total_sum_total_laps > 0 THEN LN(hws.practice_total_sum_total_laps) END), 3) as practice_total_ln_sum_total_laps,
        ROUND(AVG(hws.practice_total_min_5_lap_average_time), 3) as practice_total_avg_min_5_lap_average_time,
        ROUND(STDDEV_SAMP(TIME_TO_SEC(hws.practice_total_min_5_lap_average_time)), 3) as practice_total_stddev_min_5_lap_average_time,
        ROUND(AVG(CASE WHEN TIME_TO_SEC(hws.practice_total_min_5_lap_average_time) > 0 THEN LN(TIME_TO_SEC(hws.practice_total_min_5_lap_average_time)) END), 3) as practice_total_ln_min_5_lap_average_time,
        ROUND(AVG(hws.practice_total_max_5_lap_average_time), 3) as practice_total_avg_max_5_lap_average_time,
        ROUND(STDDEV_SAMP(TIME_TO_SEC(hws.practice_total_max_5_lap_average_time)), 3) as practice_total_stddev_max_5_lap_average_time,
        ROUND(AVG(CASE WHEN TIME_TO_SEC(hws.practice_total_max_5_lap_average_time) > 0 THEN LN(TIME_TO_SEC(hws.practice_total_max_5_lap_average_time)) END), 3) as practice_total_ln_max_5_lap_average_time,
        ROUND(AVG(hws.practice_total_avg_5_lap_average_time), 3) as practice_total_avg_5_lap_average_time,
        ROUND(STDDEV_SAMP(hws.practice_total_avg_5_lap_average_time), 3) as practice_total_stddev_5_lap_average_time,
        ROUND(AVG(CASE WHEN hws.practice_total_avg_5_lap_average_time > 0 THEN LN(hws.practice_total_avg_5_lap_average_time) END), 3) as practice_total_ln_5_lap_average_time,
        ROUND(AVG(hws.practice_total_min_10_lap_average_time), 3) as practice_total_avg_min_10_lap_average_time,
        ROUND(STDDEV_SAMP(TIME_TO_SEC(hws.practice_total_min_10_lap_average_time)), 3) as practice_total_stddev_min_10_lap_average_time,
        ROUND(AVG(CASE WHEN TIME_TO_SEC(hws.practice_total_min_10_lap_average_time) > 0 THEN LN(TIME_TO_SEC(hws.practice_total_min_10_lap_average_time)) END), 3) as practice_total_ln_min_10_lap_average_time,
        ROUND(AVG(hws.practice_total_max_10_lap_average_time), 3) as practice_total_avg_max_10_lap_average_time,
        ROUND(STDDEV_SAMP(TIME_TO_SEC(hws.practice_total_max_10_lap_average_time)), 3) as practice_total_stddev_max_10_lap_average_time,
        ROUND(AVG(CASE WHEN TIME_TO_SEC(hws.practice_total_max_10_lap_average_time) > 0 THEN LN(TIME_TO_SEC(hws.practice_total_max_10_lap_average_time)) END), 3) as practice_total_ln_max_10_lap_average_time,
        ROUND(AVG(hws.practice_total_avg_10_lap_average_time), 3) as practice_total_avg_10_lap_average_time,
        ROUND(STDDEV_SAMP(hws.practice_total_avg_10_lap_average_time), 3) as practice_total_stddev_10_lap_average_time,
        ROUND(AVG(CASE WHEN hws.practice_total_avg_10_lap_average_time > 0 THEN LN(hws.practice_total_avg_10_lap_average_time) END), 3) as practice_total_ln_10_lap_average_time,
        ROUND(AVG(hws.practice_total_min_20_lap_average_time), 3) as practice_total_avg_min_20_lap_average_time,
        ROUND(STDDEV_SAMP(TIME_TO_SEC(hws.practice_total_min_20_lap_average_time)), 3) as practice_total_stddev_min_20_lap_average_time,
        ROUND(AVG(CASE WHEN TIME_TO_SEC(hws.practice_total_min_20_lap_average_time) > 0 THEN LN(TIME_TO_SEC(hws.practice_total_min_20_lap_average_time)) END), 3) as practice_total_ln_min_20_lap_average_time,
        ROUND(AVG(hws.practice_total_max_20_lap_average_time), 3) as practice_total_avg_max_20_lap_average_time,
        ROUND(STDDEV_SAMP(TIME_TO_SEC(hws.practice_total_max_20_lap_average_time)), 3) as practice_total_stddev_max_20_lap_average_time,
        ROUND(AVG(CASE WHEN TIME_TO_SEC(hws.practice_total_max_20_lap_average_time) > 0 THEN LN(TIME_TO_SEC(hws.practice_total_max_20_lap_average_time)) END), 3) as practice_total_ln_max_20_lap_average_time,
        ROUND(AVG(hws.practice_total_avg_20_lap_average_time), 3) as practice_total_avg_20_lap_average_time,
        ROUND(STDDEV_SAMP(hws.practice_total_avg_20_lap_average_time), 3) as practice_total_stddev_20_lap_average_time,
        ROUND(AVG(CASE WHEN hws.practice_total_avg_20_lap_average_time > 0 THEN LN(hws.practice_total_avg_20_lap_average_time) END), 3) as practice_total_ln_20_lap_average_time,
        ROUND(AVG(hws.practice_total_min_25_lap_average_time), 3) as practice_total_avg_min_25_lap_average_time,
        ROUND(STDDEV_SAMP(TIME_TO_SEC(hws.practice_total_min_25_lap_average_time)), 3) as practice_total_stddev_min_25_lap_average_time,
        ROUND(AVG(CASE WHEN TIME_TO_SEC(hws.practice_total_min_25_lap_average_time) > 0 THEN LN(TIME_TO_SEC(hws.practice_total_min_25_lap_average_time)) END), 3) as practice_total_ln_min_25_lap_average_time,
        ROUND(AVG(hws.practice_total_max_25_lap_average_time), 3) as practice_total_avg_max_25_lap_average_time,
        ROUND(STDDEV_SAMP(TIME_TO_SEC(hws.practice_total_max_25_lap_average_time)), 3) as practice_total_stddev_max_25_lap_average_time,
        ROUND(AVG(CASE WHEN TIME_TO_SEC(hws.practice_total_max_25_lap_average_time) > 0 THEN LN(TIME_TO_SEC(hws.practice_total_max_25_lap_average_time)) END), 3) as practice_total_ln_max_25_lap_average_time,
        ROUND(AVG(hws.practice_total_avg_25_lap_average_time), 3) as practice_total_avg_25_lap_average_time,
        ROUND(STDDEV_SAMP(hws.practice_total_avg_25_lap_average_time), 3) as practice_total_stddev_25_lap_average_time,
        ROUND(AVG(CASE WHEN hws.practice_total_avg_25_lap_average_time > 0 THEN LN(hws.practice_total_avg_25_lap_average_time) END), 3) as practice_total_ln_25_lap_average_time,
        ROUND(AVG(hws.practice_total_min_30_lap_average_time), 3) as practice_total_avg_min_30_lap_average_time,
        ROUND(STDDEV_SAMP(TIME_TO_SEC(hws.practice_total_min_30_lap_average_time)), 3) as practice_total_stddev_min_30_lap_average_time,
        ROUND(AVG(CASE WHEN TIME_TO_SEC(hws.practice_total_min_30_lap_average_time) > 0 THEN LN(TIME_TO_SEC(hws.practice_total_min_30_lap_average_time)) END), 3) as practice_total_ln_min_30_lap_average_time,
        ROUND(AVG(hws.practice_total_max_30_lap_average_time), 3) as practice_total_avg_max_30_lap_average_time,
        ROUND(STDDEV_SAMP(TIME_TO_SEC(hws.practice_total_max_30_lap_average_time)), 3) as practice_total_stddev_max_30_lap_average_time,
        ROUND(AVG(CASE WHEN TIME_TO_SEC(hws.practice_total_max_30_lap_average_time) > 0 THEN LN(TIME_TO_SEC(hws.practice_total_max_30_lap_average_time)) END), 3) as practice_total_ln_max_30_lap_average_time,
        ROUND(AVG(hws.practice_total_avg_30_lap_average_time), 3) as practice_total_avg_30_lap_average_time,
        ROUND(STDDEV_SAMP(hws.practice_total_avg_30_lap_average_time), 3) as practice_total_stddev_30_lap_average_time,
        ROUND(AVG(CASE WHEN hws.practice_total_avg_30_lap_average_time > 0 THEN LN(hws.practice_total_avg_30_lap_average_time) END), 3) as practice_total_ln_30_lap_average_time,
        ROUND(AVG(hws.practice_total_min_10_lap_average_speed), 3) as practice_total_avg_min_10_lap_average_speed,
        ROUND(STDDEV_SAMP(hws.practice_total_min_10_lap_average_speed), 3) as practice_total_stddev_min_10_lap_average_speed,
        ROUND(AVG(CASE WHEN hws.practice_total_min_10_lap_average_speed > 0 THEN LN(hws.practice_total_min_10_lap_average_speed) END), 3) as practice_total_ln_min_10_lap_average_speed,
        ROUND(AVG(hws.practice_total_max_10_lap_average_speed), 3) as practice_total_avg_max_10_lap_average_speed,
        ROUND(STDDEV_SAMP(hws.practice_total_max_10_lap_average_speed), 3) as practice_total_stddev_max_10_lap_average_speed,
        ROUND(AVG(CASE WHEN hws.practice_total_max_10_lap_average_speed > 0 THEN LN(hws.practice_total_max_10_lap_average_speed) END), 3) as practice_total_ln_max_10_lap_average_speed,
        ROUND(AVG(hws.practice_total_avg_10_lap_average_speed), 3) as practice_total_avg_10_lap_average_speed,
        ROUND(STDDEV_SAMP(hws.practice_total_avg_10_lap_average_speed), 3) as practice_total_stddev_10_lap_average_speed,
        ROUND(AVG(CASE WHEN hws.practice_total_avg_10_lap_average_speed > 0 THEN LN(hws.practice_total_avg_10_lap_average_speed) END), 3) as practice_total_ln_10_lap_average_speed,
        ROUND(AVG(hws.practice_total_min_10_lap_start), 3) as practice_total_avg_min_10_lap_start,
        ROUND(STDDEV_SAMP(hws.practice_total_min_10_lap_start), 3) as practice_total_stddev_min_10_lap_start,
        ROUND(AVG(CASE WHEN hws.practice_total_min_10_lap_start > 0 THEN LN(hws.practice_total_min_10_lap_start) END), 3) as practice_total_ln_min_10_lap_start,
        ROUND(AVG(hws.practice_total_max_10_lap_start), 3) as practice_total_avg_max_10_lap_start,
        ROUND(STDDEV_SAMP(hws.practice_total_max_10_lap_start), 3) as practice_total_stddev_max_10_lap_start,
        ROUND(AVG(CASE WHEN hws.practice_total_max_10_lap_start > 0 THEN LN(hws.practice_total_max_10_lap_start) END), 3) as practice_total_ln_max_10_lap_start,
        ROUND(AVG(hws.practice_total_avg_10_lap_start), 3) as practice_total_avg_10_lap_start,
        ROUND(STDDEV_SAMP(hws.practice_total_avg_10_lap_start), 3) as practice_total_stddev_10_lap_start,
        ROUND(AVG(CASE WHEN hws.practice_total_avg_10_lap_start > 0 THEN LN(hws.practice_total_avg_10_lap_start) END), 3) as practice_total_ln_10_lap_start,
        ROUND(AVG(hws.practice_total_min_10_lap_end), 3) as practice_total_avg_min_10_lap_end,
        ROUND(STDDEV_SAMP(hws.practice_total_min_10_lap_end), 3) as practice_total_stddev_min_10_lap_end,
        ROUND(AVG(CASE WHEN hws.practice_total_min_10_lap_end > 0 THEN LN(hws.practice_total_min_10_lap_end) END), 3) as practice_total_ln_min_10_lap_end,
        ROUND(AVG(hws.practice_total_max_10_lap_end), 3) as practice_total_avg_max_10_lap_end,
        ROUND(STDDEV_SAMP(hws.practice_total_max_10_lap_end), 3) as practice_total_stddev_max_10_lap_end,
        ROUND(AVG(CASE WHEN hws.practice_total_max_10_lap_end > 0 THEN LN(hws.practice_total_max_10_lap_end) END), 3) as practice_total_ln_max_10_lap_end,
        ROUND(AVG(hws.practice_total_avg_10_lap_end), 3) as practice_total_avg_10_lap_end,
        ROUND(STDDEV_SAMP(hws.practice_total_avg_10_lap_end), 3) as practice_total_stddev_10_lap_end,
        ROUND(AVG(CASE WHEN hws.practice_total_avg_10_lap_end > 0 THEN LN(hws.practice_total_avg_10_lap_end) END), 3) as practice_total_ln_10_lap_end,
        ROUND(AVG(hws.practice_final_finish_position), 3) as practice_final_avg_finish_position,
        ROUND(STDDEV_SAMP(hws.practice_final_finish_position), 3) as practice_final_stddev_finish_position,
        ROUND(AVG(CASE WHEN hws.practice_final_finish_position > 0 THEN LN(hws.practice_final_finish_position) END), 3) as practice_final_ln_finish_position,
        ROUND(AVG(hws.practice_final_best_speed), 3) as practice_final_avg_best_speed,
        ROUND(STDDEV_SAMP(hws.practice_final_best_speed), 3) as practice_final_stddev_best_speed,
        ROUND(AVG(CASE WHEN hws.practice_final_best_speed > 0 THEN LN(hws.practice_final_best_speed) END), 3) as practice_final_ln_best_speed,
        ROUND(AVG(hws.practice_final_best_time), 3) as practice_final_avg_best_time,
        ROUND(STDDEV_SAMP(TIME_TO_SEC(hws.practice_final_best_time)), 3) as practice_final_stddev_best_time,
        ROUND(AVG(CASE WHEN TIME_TO_SEC(hws.practice_final_best_time) > 0 THEN LN(TIME_TO_SEC(hws.practice_final_best_time)) END), 3) as practice_final_ln_best_time,
        ROUND(AVG(hws.practice_final_total_laps), 3) as practice_final_avg_total_laps,
        ROUND(STDDEV_SAMP(hws.practice_final_total_laps), 3) as practice_final_stddev_total_laps,
        ROUND(AVG(CASE WHEN hws.practice_final_total_laps > 0 THEN LN(hws.practice_final_total_laps) END), 3) as practice_final_ln_total_laps,
        ROUND(AVG(hws.practice_final_5_lap_average_time), 3) as practice_final_avg_5_lap_average_time,
        ROUND(STDDEV_SAMP(TIME_TO_SEC(hws.practice_final_5_lap_average_time)), 3) as practice_final_stddev_5_lap_average_time,
        ROUND(AVG(CASE WHEN TIME_TO_SEC(hws.practice_final_5_lap_average_time) > 0 THEN LN(TIME_TO_SEC(hws.practice_final_5_lap_average_time)) END), 3) as practice_final_ln_5_lap_average_time,
        ROUND(AVG(hws.practice_final_10_lap_average_time), 3) as practice_final_avg_10_lap_average_time,
        ROUND(STDDEV_SAMP(TIME_TO_SEC(hws.practice_final_10_lap_average_time)), 3) as practice_final_stddev_10_lap_average_time,
        ROUND(AVG(CASE WHEN TIME_TO_SEC(hws.practice_final_10_lap_average_time) > 0 THEN LN(TIME_TO_SEC(hws.practice_final_10_lap_average_time)) END), 3) as practice_final_ln_10_lap_average_time,
        ROUND(AVG(hws.practice_final_20_lap_average_time), 3) as practice_final_avg_20_lap_average_time,
        ROUND(STDDEV_SAMP(TIME_TO_SEC(hws.practice_final_20_lap_average_time)), 3) as practice_final_stddev_20_lap_average_time,
        ROUND(AVG(CASE WHEN TIME_TO_SEC(hws.practice_final_20_lap_average_time) > 0 THEN LN(TIME_TO_SEC(hws.practice_final_20_lap_average_time)) END), 3) as practice_final_ln_20_lap_average_time,
        ROUND(AVG(hws.practice_final_25_lap_average_time), 3) as practice_final_avg_25_lap_average_time,
        ROUND(STDDEV_SAMP(TIME_TO_SEC(hws.practice_final_25_lap_average_time)), 3) as practice_final_stddev_25_lap_average_time,
        ROUND(AVG(CASE WHEN TIME_TO_SEC(hws.practice_final_25_lap_average_time) > 0 THEN LN(TIME_TO_SEC(hws.practice_final_25_lap_average_time)) END), 3) as practice_final_ln_25_lap_average_time,
        ROUND(AVG(hws.practice_final_30_lap_average_time), 3) as practice_final_avg_30_lap_average_time,
        ROUND(STDDEV_SAMP(TIME_TO_SEC(hws.practice_final_30_lap_average_time)), 3) as practice_final_stddev_30_lap_average_time,
        ROUND(AVG(CASE WHEN TIME_TO_SEC(hws.practice_final_30_lap_average_time) > 0 THEN LN(TIME_TO_SEC(hws.practice_final_30_lap_average_time)) END), 3) as practice_final_ln_30_lap_average_time,
        ROUND(AVG(hws.practice_final_10_lap_average_speed), 3) as practice_final_avg_10_lap_average_speed,
        ROUND(STDDEV_SAMP(hws.practice_final_10_lap_average_speed), 3) as practice_final_stddev_10_lap_average_speed,
        ROUND(AVG(CASE WHEN hws.practice_final_10_lap_average_speed > 0 THEN LN(hws.practice_final_10_lap_average_speed) END), 3) as practice_final_ln_10_lap_average_speed,
        ROUND(AVG(hws.practice_final_10_lap_start), 3) as practice_final_avg_10_lap_start,
        ROUND(STDDEV_SAMP(hws.practice_final_10_lap_start), 3) as practice_final_stddev_10_lap_start,
        ROUND(AVG(CASE WHEN hws.practice_final_10_lap_start > 0 THEN LN(hws.practice_final_10_lap_start) END), 3) as practice_final_ln_10_lap_start,
        ROUND(AVG(hws.practice_final_10_lap_end), 3) as practice_final_avg_10_lap_end,
        ROUND(STDDEV_SAMP(hws.practice_final_10_lap_end), 3) as practice_final_stddev_10_lap_end,
        ROUND(AVG(CASE WHEN hws.practice_final_10_lap_end > 0 THEN LN(hws.practice_final_10_lap_end) END), 3) as practice_final_ln_10_lap_end,
        COUNT(*) as races_total
    FROM nascar.hist_weeks_stats hws
    WHERE hws.series_id = r_series_id
        AND hws.season_id = r_season_id
        AND hws.week_id = r_week_id
        AND hws.deleted_at IS NULL
        -- AND hws.car_status = 'Running' TODO: Consider making this an ENUM and filtering by only running
    GROUP BY hws.series_id, hws.season_id, hws.track_id, hws.driver_id
    ;
END //

DELIMITER ;
